package com.f776.ecopan.api.seed

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

/**
 * On-disk shape of `seed/<name>-sales.json`, generated by `ecopan_ml.demo.seed_sales` (plan 11
 * SEED-2, plan 08 §6).
 *
 * A **demand curve**, not a list of tickets: one row per (day, branch, product) carrying an item
 * count. [SeedSalesExpander] turns that into sales and lines at load time. The split exists because
 * the exploded form of the same 120 days is ~37 MB and ~36k rows — not something to commit or to
 * insert on every container start — and because pricing belongs on the backend side of the wire,
 * where the integer-minor rules (01 §5) already live.
 */
@Serializable
data class SeedSalesDocument(
    /** Carried through from the generator so the quarantine notice survives being read and re-read. */
    @SerialName("_warning") val warning: String = "",
    val generator: String = "",
    val days: Int = 0,
    /** Last day the generator produced, ISO-8601. The anchor for the whole-week shift. */
    val lastDay: String,
    val rows: List<SeedSalesRow> = emptyList()
)

@Serializable
data class SeedSalesRow(
    /** ISO-8601 local date. */
    val day: String,
    val branchId: String,
    val productId: String,
    /** Loaves for a WEIGHT product, units for a UNIT product. */
    val items: Int
)
